abstract class AuthHandler(string issuer)
{
    public string Issuer { get; } = issuer;
    public abstract AuthToken Parse(string raw);
}

sealed class LtiHandler(string issuer, string clientId) : AuthHandler(issuer)
{
    public string ClientId { get; } = clientId;

    public override AuthToken Parse(string raw) =>
        new AuthToken(raw, Issuer, ClientId);
}

// abstract: cannot new, may have abstract members
abstract class Shape
{
    public abstract double Area();
}

// sealed: cannot derive further
sealed class Circle(double radius) : Shape
{
    public override double Area() => Math.PI * radius * radius;
}

