interface IAuditable
{
    DateTimeOffset CreatedAt { get; }
}

abstract class Entity(string id) : IAuditable
{
    public string Id { get; } = id;
    public DateTimeOffset CreatedAt { get; } = DateTimeOffset.UtcNow;
}

sealed class Order(string id, decimal total) : Entity(id)
{
    public decimal Total { get; } = total;
}

abstract class AuthHandler(string issuer)
{
    protected string Issuer { get; } = issuer;
